1	/**
2	 * ============================================================================
3	 * HILO AVIATION - Parts Inventory Routes (M-02)
4	 * ============================================================================
5	 *
6	 * Endpoints:
7	 *   GET   /parts                       — list parts catalog for an org
8	 *   POST  /parts                       — add a new part to the catalog
9	 *   GET   /parts/:id                   — get single part with detail
10	 *   PATCH /parts/:id                   — update a part's catalog fields
11	 *   GET   /parts/:id/transactions      — paginated ledger with running balance
12	 *   POST  /parts/:id/transactions      — record a stock movement
13	 *
14	 * ============================================================================
15	 */
16	
17	import { aiGateway } from '@/lib/ai-control-center';
18	import { db } from '@/lib/db';
19	import * as schema from '@/lib/schema';
20	import { ensureOrgScope, ensureWorkOrderScope } from '@/server/helpers';
21	import type { AuthUser } from '@/server/middleware/auth';
22	import { requireAuth } from '@/server/middleware/auth';
23	import { recordAiTokenUsage } from '@/server/routes/routes-integration-usage';
24	import { and, desc, eq, ilike, or, sql } from 'drizzle-orm';
25	import { Hono } from 'hono';
26	
27	export const partsRouter = new Hono<{ Variables: { authUser?: AuthUser } }>();
28	
29	// ─── Constants ────────────────────────────────────────────────────────────────
30	
31	const VALID_CATEGORIES = new Set([
32	  'engine',
33	  'airframe',
34	  'avionics',
35	  'consumable',
36	  'hardware',
37	  'safety_equipment',
38	]);
39	
40	const VALID_TRANSACTION_TYPES = new Set([
41	  'purchase_receipt',
42	  'wo_issue',
43	  'wo_return',
44	  'adjustment_add',
45	  'adjustment_remove',
46	  'transfer_out',
47	  'transfer_in',
48	  'core_return',
49	  // Legacy values from earlier schema (keep accepting for backward compatibility)
50	  'received',
51	  'issued',
52	  'returned',
53	  'adjusted',
54	]);
55	
56	// ─── Helpers ─────────────────────────────────────────────────────────────────
57	
58	function deriveStatus(
59	  qtyAvailable: number,
60	  reorderPoint: number | null,
61	  shelfLifeExpiry: Date | null,
62	): string {
63	  if (qtyAvailable <= 0) return 'out_of_stock';
64	
65	  if (shelfLifeExpiry) {
66	    const daysUntilExpiry =
67	      (shelfLifeExpiry.getTime() - Date.now()) / (1000 * 60 * 60 * 24);
68	    if (daysUntilExpiry <= 30) return 'expiring_soon';
69	    if (daysUntilExpiry < 0) return 'expired';
70	  }
71	
72	  if (reorderPoint !== null && qtyAvailable <= reorderPoint) {
73	    return 'low_stock';
74	  }
75	
76	  return 'in_stock';
77	}
78	
79	function safeErrorMessage(err: unknown): string {
80	  return err instanceof Error
81	    ? err.message
82	    : typeof err === 'object' && err !== null
83	      ? JSON.stringify(err)
84	      : String(err);
85	}
86	
87	// ─── GET /parts ───────────────────────────────────────────────────────────────
88	
89	partsRouter.get('/parts', requireAuth(), async (c) => {
90	  const { orgId, status, q, locationId, category } = c.req.query();
91	
92	  if (!orgId) {
93	    return c.json({ error: 'orgId is required' }, 400);
94	  }
95	  const denied = await ensureOrgScope(c, orgId);
96	  if (denied) return denied;
97	
98	  try {
99	    const conditions = [eq(schema.partsCatalog.flightSchoolId, orgId)];
100	
101	    if (locationId) {
102	      conditions.push(eq(schema.partsCatalog.locationId, locationId));
103	    }
104	    if (category && VALID_CATEGORIES.has(category)) {
105	      conditions.push(eq(schema.partsCatalog.category, category));
106	    }
107	    if (q) {
108	      conditions.push(
109	        or(
110	          ilike(schema.partsCatalog.partNumber, `%${q}%`),
111	          ilike(schema.partsCatalog.description, `%${q}%`),
112	          ilike(schema.partsCatalog.name, `%${q}%`),
113	        ) as ReturnType<typeof eq>,
114	      );
115	    }
116	
117	    const rows = await db
118	      .select()
119	      .from(schema.partsCatalog)
120	      .where(and(...conditions))
121	      .orderBy(schema.partsCatalog.partNumber)
122	      .limit(500);
123	
124	    const parts = rows.map((p) => {
125	      const qtyAvailable = p.qtyOnHand - p.qtyReserved;
126	      const computedStatus = deriveStatus(
127	        qtyAvailable,
128	        p.reorderPoint,
129	        p.shelfLifeExpiry,
130	      );
131	
132	      return {
133	        ...p,
134	        qtyAvailable,
135	        unitCost: p.unitCost !== null ? Number(p.unitCost) : null,
136	        status: computedStatus,
137	      };
138	    });
139	
140	    // Filter by status after derivation
141	    const filtered =
142	      status && status !== 'all'
143	        ? parts.filter((p) => p.status === status)
144	        : parts;
145	
146	    // Build summary
147	    const summary = {
148	      in_stock: parts.filter((p) => p.status === 'in_stock').length,
149	      low_stock: parts.filter((p) => p.status === 'low_stock').length,
150	      out_of_stock: parts.filter((p) => p.status === 'out_of_stock').length,
151	      expiring_soon: parts.filter((p) => p.status === 'expiring_soon').length,
152	      expired: parts.filter((p) => p.status === 'expired').length,
153	    };
154	
155	    return c.json({ parts: filtered, summary });
156	  } catch (err) {
157	    console.error('[parts GET /] Error:', safeErrorMessage(err));
158	    return c.json({ error: 'Failed to fetch parts' }, 500);
159	  }
160	});
161	
162	// ─── POST /parts ──────────────────────────────────────────────────────────────
163	
164	partsRouter.post('/parts', requireAuth(), async (c) => {
165	  const { orgId } = c.req.query();
166	
167	  if (!orgId) {
168	    return c.json({ error: 'orgId is required' }, 400);
169	  }
170	  const denied = await ensureOrgScope(c, orgId);
171	  if (denied) return denied;
172	
173	  let body: Record<string, unknown>;
174	  try {
175	    body = await c.req.json();
176	  } catch {
177	    return c.json({ error: 'Invalid JSON body' }, 400);
178	  }
179	
180	  const { partNumber, category } = body as {
181	    partNumber?: string;
182	    description?: string;
183	    category?: string;
184	    name?: string;
185	  };
186	
187	  if (!partNumber || !category) {
188	    return c.json({ error: 'partNumber and category are required' }, 400);
189	  }
190	
191	  const initialQty =
192	    typeof body.initialQty === 'number'
193	      ? Math.max(0, Math.floor(body.initialQty))
194	      : 0;
195	
196	  try {
197	    const [created] = await db
198	      .insert(schema.partsCatalog)
199	      .values({
200	        flightSchoolId: orgId,
201	        locationId: body.locationId ? String(body.locationId) : undefined,
202	        name: body.name ? String(body.name) : undefined,
203	        partNumber: String(partNumber),
204	        description: body.description ? String(body.description) : null,
205	        category: String(category),
206	        alternatePns: body.alternatePns ? String(body.alternatePns) : undefined,
207	        qtyOnHand: initialQty,
208	        reorderPoint:
209	          typeof body.reorderPoint === 'number' ? body.reorderPoint : undefined,
210	        reorderQty:
211	          typeof body.reorderQty === 'number' ? body.reorderQty : undefined,
212	        unitCost: body.unitCost ? String(body.unitCost) : undefined,
213	        shelfLocation: body.shelfLocation
214	          ? String(body.shelfLocation)
215	          : undefined,
216	        preferredSupplier: body.preferredSupplier
217	          ? String(body.preferredSupplier)
218	          : undefined,
219	        shelfLifeExpiry: body.shelfLifeExpiry
220	          ? new Date(String(body.shelfLifeExpiry))
221	          : undefined,
222	        airworthinessCertAttached:
223	          typeof body.airworthinessCertAttached === 'boolean'
224	            ? body.airworthinessCertAttached
225	            : false,
226	        aircraftApplicability: Array.isArray(body.aircraftApplicability)
227	          ? (body.aircraftApplicability as string[]).map(String)
228	          : undefined,
229	        adReferences: Array.isArray(body.adReferences)
230	          ? (body.adReferences as string[]).map(String)
231	          : undefined,
232	      })
233	      .returning();
234	
235	    // If initial quantity is set, record a purchase_receipt transaction
236	    if (initialQty > 0) {
237	      await db.insert(schema.partsInventoryTransactions).values({
238	        flightSchoolId: orgId,
239	        partId: created.id,
240	        type: 'purchase_receipt',
241	        qty: initialQty,
242	        performedBy: String(body.performedBy ?? 'system'),
243	        notes: 'Initial stock on creation',
244	      });
245	    }
246	
247	    return c.json({ part: created }, 201);
248	  } catch (err) {
249	    console.error('[parts POST /] Error:', safeErrorMessage(err));
250	    return c.json({ error: 'Failed to create part' }, 500);
251	  }
252	});
253	
254	// ─── GET /parts/:id ───────────────────────────────────────────────────────────
255	
256	partsRouter.get('/parts/:id', requireAuth(), async (c) => {
257	  const { orgId } = c.req.query();
258	  const { id } = c.req.param();
259	
260	  if (!orgId) {
261	    return c.json({ error: 'orgId is required' }, 400);
262	  }
263	  const denied = await ensureOrgScope(c, orgId);
264	  if (denied) return denied;
265	
266	  try {
267	    const [row] = await db
268	      .select()
269	      .from(schema.partsCatalog)
270	      .where(
271	        and(
272	          eq(schema.partsCatalog.id, id),
273	          eq(schema.partsCatalog.flightSchoolId, orgId),
274	        ),
275	      )
276	      .limit(1);
277	
278	    if (!row) {
279	      return c.json({ error: 'Part not found' }, 404);
280	    }
281	
282	    // Fetch recent transactions (last 50) for the activity log
283	    const txs = await db
284	      .select()
285	      .from(schema.partsInventoryTransactions)
286	      .where(eq(schema.partsInventoryTransactions.partId, id))
287	      .orderBy(desc(schema.partsInventoryTransactions.createdAt))
288	      .limit(50);
289	
290	    // Fetch work orders that reference this part (include type for AD highlighting)
291	    const woParts = await db
292	      .select({
293	        id: schema.workOrderParts.id,
294	        workOrderId: schema.workOrderParts.workOrderId,
295	        qtyRequired: schema.workOrderParts.qtyRequired,
296	        qtyUsed: schema.workOrderParts.qtyUsed,
297	        notes: schema.workOrderParts.notes,
298	        createdAt: schema.workOrderParts.createdAt,
299	        workOrderNumber: schema.workOrders.workOrderNumber,
300	        workOrderTitle: schema.workOrders.title,
301	        workOrderStatus: schema.workOrders.status,
302	        workOrderType: schema.workOrders.type,
303	      })
304	      .from(schema.workOrderParts)
305	      .innerJoin(
306	        schema.workOrders,
307	        eq(schema.workOrderParts.workOrderId, schema.workOrders.id),
308	      )
309	      .where(eq(schema.workOrderParts.partId, id))
310	      .orderBy(desc(schema.workOrders.createdAt))
311	      .limit(20);
312	
313	    const qtyAvailable = row.qtyOnHand - row.qtyReserved;
314	
315	    // Build running balance for transaction ledger
316	    let runningBalance = row.qtyOnHand;
317	    const transactions = txs.map((tx) => {
318	      const balance = runningBalance;
319	      runningBalance -= tx.qty; // going backwards in time
320	      return {
321	        ...tx,
322	        performedByName: tx.performedBy,
323	        workOrderNumber: null,
324	        balanceAfter: balance,
325	      };
326	    });
327	
328	    const part = {
329	      ...row,
330	      qtyAvailable,
331	      unitCost: row.unitCost !== null ? Number(row.unitCost) : null,
332	      status: deriveStatus(qtyAvailable, row.reorderPoint, row.shelfLifeExpiry),
333	    };
334	
335	    return c.json({ part, transactions, workOrders: woParts });
336	  } catch (err) {
337	    console.error('[parts GET /:id] Error:', safeErrorMessage(err));
338	    return c.json({ error: 'Failed to fetch part' }, 500);
339	  }
340	});
341	
342	// ─── PATCH /parts/:id ────────────────────────────────────────────────────────
343	
344	partsRouter.patch('/parts/:id', requireAuth(), async (c) => {
345	  const { orgId } = c.req.query();
346	  const { id } = c.req.param();
347	
348	  if (!orgId) {
349	    return c.json({ error: 'orgId is required' }, 400);
350	  }
351	  const denied = await ensureOrgScope(c, orgId);
352	  if (denied) return denied;
353	
354	  let body: Record<string, unknown>;
355	  try {
356	    body = await c.req.json();
357	  } catch {
358	    return c.json({ error: 'Invalid JSON body' }, 400);
359	  }
360	
361	  try {
362	    // Verify the part belongs to this org
363	    const [existing] = await db
364	      .select({ id: schema.partsCatalog.id })
365	      .from(schema.partsCatalog)
366	      .where(
367	        and(
368	          eq(schema.partsCatalog.id, id),
369	          eq(schema.partsCatalog.flightSchoolId, orgId),
370	        ),
371	      )
372	      .limit(1);
373	
374	    if (!existing) {
375	      return c.json({ error: 'Part not found' }, 404);
376	    }
377	
378	    const updates: Partial<schema.PartsCatalog> = {
379	      updatedAt: new Date(),
380	    };
381	
382	    if (typeof body.name === 'string') updates.name = body.name;
383	    if (typeof body.partNumber === 'string')
384	      updates.partNumber = body.partNumber;
385	    if (typeof body.description === 'string')
386	      updates.description = body.description;
387	    if (typeof body.category === 'string') updates.category = body.category;
388	    if (typeof body.alternatePns === 'string')
389	      updates.alternatePns = body.alternatePns;
390	    if (typeof body.reorderPoint === 'number')
391	      updates.reorderPoint = body.reorderPoint;
392	    if (typeof body.reorderQty === 'number')
393	      updates.reorderQty = body.reorderQty;
394	    if (typeof body.unitCost !== 'undefined')
395	      updates.unitCost = body.unitCost !== null ? String(body.unitCost) : null;
396	    if (typeof body.shelfLocation === 'string')
397	      updates.shelfLocation = body.shelfLocation;
398	    if (typeof body.preferredSupplier === 'string')
399	      updates.preferredSupplier = body.preferredSupplier;
400	    if (typeof body.airworthinessCertAttached === 'boolean')
401	      updates.airworthinessCertAttached = body.airworthinessCertAttached;
402	    if (typeof body.shelfLifeExpiry !== 'undefined')
403	      updates.shelfLifeExpiry = body.shelfLifeExpiry
404	        ? new Date(String(body.shelfLifeExpiry))
405	        : null;
406	    if (Array.isArray(body.aircraftApplicability))
407	      updates.aircraftApplicability = (
408	        body.aircraftApplicability as string[]
409	      ).map(String);
410	    if (Array.isArray(body.adReferences))
411	      updates.adReferences = (body.adReferences as string[]).map(String);
412	
413	    const [updated] = await db
414	      .update(schema.partsCatalog)
415	      .set(updates)
416	      .where(eq(schema.partsCatalog.id, id))
417	      .returning();
418	
419	    return c.json({ part: updated });
420	  } catch (err) {
421	    console.error('[parts PATCH /:id] Error:', safeErrorMessage(err));
422	    return c.json({ error: 'Failed to update part' }, 500);
423	  }
424	});
425	
426	// ─── GET /parts/:id/transactions ─────────────────────────────────────────────
427	
428	partsRouter.get('/parts/:id/transactions', requireAuth(), async (c) => {
429	  const { orgId } = c.req.query();
430	  const { id } = c.req.param();
431	
432	  if (!orgId) {
433	    return c.json({ error: 'orgId is required' }, 400);
434	  }
435	  const denied = await ensureOrgScope(c, orgId);
436	  if (denied) return denied;
437	
438	  try {
439	    // Verify part belongs to org
440	    const [part] = await db
441	      .select({
442	        id: schema.partsCatalog.id,
443	        qtyOnHand: schema.partsCatalog.qtyOnHand,
444	      })
445	      .from(schema.partsCatalog)
446	      .where(
447	        and(
448	          eq(schema.partsCatalog.id, id),
449	          eq(schema.partsCatalog.flightSchoolId, orgId),
450	        ),
451	      )
452	      .limit(1);
453	
454	    if (!part) {
455	      return c.json({ error: 'Part not found' }, 404);
456	    }
457	
458	    const txs = await db
459	      .select()
460	      .from(schema.partsInventoryTransactions)
461	      .where(eq(schema.partsInventoryTransactions.partId, id))
462	      .orderBy(desc(schema.partsInventoryTransactions.createdAt))
463	      .limit(200);
464	
465	    // Compute running balance (current qty is the anchor)
466	    let balance = part.qtyOnHand;
467	    const transactions = txs.map((tx) => {
468	      const balanceAfter = balance;
469	      balance -= tx.qty;
470	      return {
471	        ...tx,
472	        performedByName: tx.performedBy,
473	        balanceAfter,
474	      };
475	    });
476	
477	    return c.json({ transactions });
478	  } catch (err) {
479	    console.error(
480	      '[parts GET /:id/transactions] Error:',
481	      safeErrorMessage(err),
482	    );
483	    return c.json({ error: 'Failed to fetch transactions' }, 500);
484	  }
485	});
486	
487	// ─── DELETE /parts/:id ───────────────────────────────────────────────────────
488	
489	partsRouter.delete('/parts/:id', requireAuth(), async (c) => {
490	  const { orgId } = c.req.query();
491	  const { id } = c.req.param();
492	
493	  if (!orgId) {
494	    return c.json({ error: 'orgId is required' }, 400);
495	  }
496	  const denied = await ensureOrgScope(c, orgId);
497	  if (denied) return denied;
498	
499	  try {
500	    const [existing] = await db
501	      .select({ id: schema.partsCatalog.id })
502	      .from(schema.partsCatalog)
503	      .where(
504	        and(
505	          eq(schema.partsCatalog.id, id),
506	          eq(schema.partsCatalog.flightSchoolId, orgId),
507	        ),
508	      )
509	      .limit(1);
510	
511	    if (!existing) {
512	      return c.json({ error: 'Part not found' }, 404);
513	    }
514	
515	    // Delete associated transactions and work_order_parts first (FK constraints)
516	    await db
517	      .delete(schema.partsInventoryTransactions)
518	      .where(eq(schema.partsInventoryTransactions.partId, id));
519	
520	    await db
521	      .delete(schema.workOrderParts)
522	      .where(eq(schema.workOrderParts.partId, id));
523	
524	    await db.delete(schema.partsCatalog).where(eq(schema.partsCatalog.id, id));
525	
526	    return c.json({ deleted: true }, 200);
527	  } catch (err) {
528	    console.error('[parts DELETE /:id] Error:', safeErrorMessage(err));
529	    return c.json({ error: 'Failed to delete part' }, 500);
530	  }
531	});
532	
533	// ─── POST /parts/:id/transactions ────────────────────────────────────────────
534	
535	partsRouter.post('/parts/:id/transactions', requireAuth(), async (c) => {
536	  const { orgId } = c.req.query();
537	  const { id } = c.req.param();
538	
539	  if (!orgId) {
540	    return c.json({ error: 'orgId is required' }, 400);
541	  }
542	  const denied = await ensureOrgScope(c, orgId);
543	  if (denied) return denied;
544	
545	  let body: Record<string, unknown>;
546	  try {
547	    body = await c.req.json();
548	  } catch {
549	    return c.json({ error: 'Invalid JSON body' }, 400);
550	  }
551	
552	  const { transactionType, quantity, workOrderId, notes, performedBy } =
553	    body as {
554	      transactionType?: string;
555	      quantity?: number;
556	      workOrderId?: string;
557	      notes?: string;
558	      performedBy?: string;
559	    };
560	
561	  if (!transactionType || !VALID_TRANSACTION_TYPES.has(transactionType)) {
562	    return c.json(
563	      {
564	        error: `transactionType must be one of: ${[...VALID_TRANSACTION_TYPES].join(', ')}`,
565	      },
566	      400,
567	    );
568	  }
569	
570	  if (typeof quantity !== 'number' || quantity === 0) {
571	    return c.json({ error: 'quantity must be a non-zero number' }, 400);
572	  }
573	
574	  // Tenant isolation: workOrderId is caller-supplied, is stamped onto the
575	  // transaction row, and drives the `awaiting_parts` status update below —
576	  // which has no flight_school_id predicate of its own.
577	  if (workOrderId) {
578	    const woDenied = await ensureWorkOrderScope(c, workOrderId);
579	    if (woDenied) return woDenied;
580	  }
581	
582	  // Determine signed quantity: negative types should produce negative qty
583	  const negativeTypes = new Set([
584	    'wo_issue',
585	    'adjustment_remove',
586	    'transfer_out',
587	    'issued',
588	    'adjusted',
589	  ]);
590	  const signedQty = negativeTypes.has(transactionType)
591	    ? -Math.abs(quantity)
592	    : Math.abs(quantity);
593	
594	  try {
595	    // Fetch current part to verify ownership and check qty
596	    const [part] = await db
597	      .select()
598	      .from(schema.partsCatalog)
599	      .where(
600	        and(
601	          eq(schema.partsCatalog.id, id),
602	          eq(schema.partsCatalog.flightSchoolId, orgId),
603	        ),
604	      )
605	      .limit(1);
606	
607	    if (!part) {
608	      return c.json({ error: 'Part not found' }, 404);
609	    }
610	
611	    // Prevent negative qty on hand
612	    if (part.qtyOnHand + signedQty < 0) {
613	      return c.json(
614	        {
615	          error: `Insufficient stock. On hand: ${part.qtyOnHand}, requested: ${Math.abs(quantity)}`,
616	        },
617	        422,
618	      );
619	    }
620	
621	    // Insert transaction
622	    const [tx] = await db
623	      .insert(schema.partsInventoryTransactions)
624	      .values({
625	        flightSchoolId: orgId,
626	        partId: id,
627	        type: transactionType,
628	        qty: signedQty,
629	        performedBy: String(performedBy ?? 'system'),
630	        workOrderId: workOrderId ?? undefined,
631	        notes: notes ? String(notes) : undefined,
632	      })
633	      .returning();
634	
635	    // Update qty_on_hand and (if WO issue) qty_reserved on the catalog record
636	    const qtyUpdates: { qtyOnHand: number; qtyReserved?: number } = {
637	      qtyOnHand: part.qtyOnHand + signedQty,
638	    };
639	
640	    if (transactionType === 'wo_issue' || transactionType === 'issued') {
641	      qtyUpdates.qtyReserved = Math.max(
642	        0,
643	        part.qtyReserved + Math.abs(quantity),
644	      );
645	    } else if (
646	      transactionType === 'wo_return' ||
647	      transactionType === 'returned'
648	    ) {
649	      qtyUpdates.qtyReserved = Math.max(
650	        0,
651	        part.qtyReserved - Math.abs(quantity),
652	      );
653	    }
654	
655	    await db
656	      .update(schema.partsCatalog)
657	      .set({ ...qtyUpdates, updatedAt: new Date() })
658	      .where(eq(schema.partsCatalog.id, id));
659	
660	    // Recalculate status for the updated part
661	    const newQtyAvailable =
662	      qtyUpdates.qtyOnHand - (qtyUpdates.qtyReserved ?? part.qtyReserved);
663	    const status = deriveStatus(
664	      newQtyAvailable,
665	      part.reorderPoint,
666	      part.shelfLifeExpiry,
667	    );
668	
669	    // If WO issue drives stock to 0 and there are open WOs, update WO status
670	    if (
671	      (transactionType === 'wo_issue' || transactionType === 'issued') &&
672	      workOrderId &&
673	      newQtyAvailable <= 0
674	    ) {
675	      try {
676	        await db
677	          .update(schema.workOrders)
678	          .set({
679	            status: 'awaiting_parts',
680	            updatedAt: new Date(),
681	          })
682	          .where(
683	            and(
684	              eq(schema.workOrders.id, workOrderId),
685	              sql`${schema.workOrders.status} NOT IN ('complete', 'closed', 'voided')`,
686	            ),
687	          );
688	      } catch {
689	        // Non-fatal — log but don't fail the transaction
690	        console.warn(
691	          '[parts POST /:id/transactions] Failed to update WO status',
692	        );
693	      }
694	    }
695	
696	    return c.json(
697	      {
698	        transaction: tx,
699	        updatedQty: {
700	          qtyOnHand: qtyUpdates.qtyOnHand,
701	          qtyReserved: qtyUpdates.qtyReserved ?? part.qtyReserved,
702	          qtyAvailable: newQtyAvailable,
703	          status,
704	        },
705	      },
706	      201,
707	    );
708	  } catch (err) {
709	    console.error(
710	      '[parts POST /:id/transactions] Error:',
711	      safeErrorMessage(err),
712	    );
713	    return c.json({ error: 'Failed to record transaction' }, 500);
714	  }
715	});
