11	 *   PATCH /part-installations/:id/mark-removed — mark a part as removed
12	 *   DELETE /part-installations/:id         — soft delete (admin)
13	 *
14	 * ============================================================================
15	 */
16	
17	import { db } from '@/lib/db';
18	import * as schema from '@/lib/schema';
19	import { ensureEquipmentScope, ensureOrgScope, isUuid } from '@/server/helpers';
20	import { type AuthUser, requireAuth } from '@/server/middleware/auth';
21	import { and, asc, desc, eq, ilike, isNull, or, sql } from 'drizzle-orm';
22	import type { AnyPgColumn, PgTable } from 'drizzle-orm/pg-core';
23	import { Hono } from 'hono';
24	
25	export const partInstallationsRouter = new Hono<{
26	  Variables: { authUser?: AuthUser };
27	}>();
28	
29	type ScopedTable = PgTable & { id: AnyPgColumn; flightSchoolId: AnyPgColumn };
30	
31	/**
32	 * Caller-supplied foreign keys accepted by this resource. Every target table is
33	 * tenant-scoped, but Postgres has no composite FK tying them to
34	 * `part_installations.flight_school_id` — so a row can otherwise be written
35	 * with the caller's own school while pointing at another school's work order,
36	 * logbook entry, discrepancy, or part.
37	 */
38	const SCOPED_REFERENCES: ReadonlyArray<{ field: string; table: ScopedTable }> =
39	  [
40	    { field: 'partId', table: schema.partsCatalog },
41	    { field: 'workOrderId', table: schema.workOrders },
42	    { field: 'logbookEntryId', table: schema.aircraftLogbookEntries },
43	    { field: 'discrepancyId', table: schema.maintenanceDiscrepancies },
44	    { field: 'replacedPartId', table: schema.partInstallations },
45	  ];
46	
47	/**
48	 * Returns the name of the first supplied reference that does not resolve inside
49	 * `orgId`, or `null` when every supplied reference is in-scope. `orgId` has
50	 * already been proven to be the caller's own school by `ensureOrgScope`, so a
51	 * scoped existence check is sufficient here.
52	 */
53	async function findForeignReference(
54	  values: Record<string, unknown>,
55	  orgId: string,
56	): Promise<string | null> {
57	  for (const { field, table } of SCOPED_REFERENCES) {
58	    const id = values[field];
59	    if (id === undefined || id === null) continue;
60	    if (typeof id !== 'string' || !isUuid(id)) return field;
61	    const [row] = await db
62	      .select({ id: table.id })
63	      .from(table)
64	      .where(and(eq(table.id, id), eq(table.flightSchoolId, orgId)))
65	      .limit(1);
66	    if (!row) return field;
67	  }
68	  return null;
69	}
70	
71	function safeErrorMessage(err: unknown): string {
72	  return err instanceof Error
73	    ? err.message
74	    : typeof err === 'object' && err !== null
75	      ? JSON.stringify(err)
76	      : String(err);
77	}
