79	const VALID_CATEGORIES = new Set([
80	  'engine',
81	  'airframe',
82	  'electrical',
83	  'avionics',
84	  'propeller',
85	  'fuel_system',
86	  'flight_controls',
87	  'landing_gear',
88	  'instruments',
89	  'consumable',
90	  'other',
91	]);
