93	const VALID_CONDITIONS = new Set([
94	  'new',
95	  'overhauled',
96	  'serviceable',
97	  'repaired',
98	  'as_removed',
99	]);
100	
101	const VALID_ACTIONS = new Set([
102	  'installed',
103	  'removed',
104	  'inspected',
105	  'replaced',
106	]);
107	
108	const VALID_SOURCES = new Set([
109	  'scan',
110	  'work_order',
111	  'discrepancy',
112	  'manual',
113	  'import',
114	]);
