118	partInstallationsRouter.get('/part-installations', requireAuth(), async (c) => {
119	  const { orgId, equipmentId, category, action, q, sort, lifeLimited } =
120	    c.req.query();
121	
122	  if (!orgId) return c.json({ error: 'orgId is required' }, 400);
123	  if (!equipmentId) return c.json({ error: 'equipmentId is required' }, 400);
124	  // Tenant isolation: orgId and equipmentId are both caller-supplied filters.
125	  const denied = await ensureOrgScope(c, orgId);
126	  if (denied) return denied;
127	
128	  try {
129	    const conditions = [
130	      eq(schema.partInstallations.flightSchoolId, orgId),
131	      eq(schema.partInstallations.aircraftId, equipmentId),
132	      isNull(schema.partInstallations.deletedAt),
133	    ];
134	
135	    if (category && VALID_CATEGORIES.has(category)) {
136	      conditions.push(eq(schema.partInstallations.category, category));
137	    }
138	
139	    if (action && VALID_ACTIONS.has(action)) {
140	      conditions.push(eq(schema.partInstallations.action, action));
141	    }
142	
143	    if (lifeLimited === 'true') {
144	      conditions.push(eq(schema.partInstallations.isLifeLimited, true));
145	    }
146	
147	    if (q) {
148	      const orClause = or(
149	        ilike(schema.partInstallations.partName, `%${q}%`),
150	        ilike(schema.partInstallations.partNumber, `%${q}%`),
151	        ilike(schema.partInstallations.manufacturer, `%${q}%`),
152	        ilike(schema.partInstallations.serialNumber, `%${q}%`),
153	        ilike(schema.partInstallations.notes, `%${q}%`),
154	        ilike(schema.partInstallations.installedBy, `%${q}%`),
155	      );
156	      if (orClause) conditions.push(orClause);
157	    }
158	
159	    let orderBy: ReturnType<typeof asc>[];
160	    if (sort === 'oldest') {
161	      orderBy = [asc(schema.partInstallations.installedAt)];
162	    } else if (sort === 'cost_desc') {
163	      orderBy = [desc(schema.partInstallations.unitCost)];
164	    } else if (sort === 'category') {
165	      orderBy = [
166	        asc(schema.partInstallations.category),
167	        desc(schema.partInstallations.installedAt),
168	      ];
169	    } else {
170	      orderBy = [desc(schema.partInstallations.installedAt)];
171	    }
172	
173	    const rows = await db
174	      .select()
175	      .from(schema.partInstallations)
176	      .where(and(...conditions))
177	      .orderBy(...orderBy);
178	
179	    return c.json({ data: rows });
180	  } catch (err) {
181	    console.error('[GET /part-installations]', safeErrorMessage(err));
182	    return c.json({ error: 'Failed to fetch part installations' }, 500);
183	  }
