349	partInstallationsRouter.patch(
350	  '/part-installations/:id',
351	  requireAuth(),
352	  async (c) => {
353	    const { id } = c.req.param();
354	    const body = await c.req.json();
355	    const { orgId } = body;
356	
357	    if (!orgId) return c.json({ error: 'orgId is required' }, 400);
358	    const denied = await ensureOrgScope(c, orgId);
359	    if (denied) return denied;
360	
361	    const allowedFields = [
362	      'partNumber',
363	      'partName',
364	      'manufacturer',
365	      'serialNumber',
366	      'category',
367	      'ataChapter',
368	      'condition',
369	      'action',
370	      'unitCost',
371	      'installedBy',
372	      'apCertNumber',
373	      'installedAt',
374	      'aircraftHours',
375	      'workOrderId',
376	      'logbookEntryId',
377	      'discrepancyId',
378	      'replacedPartId',
379	      'expectedLifeHrs',
380	      'expectedLifeMo',
381	      'isLifeLimited',
382	      'notes',
383	    ];
384	
385	    const updates: Record<string, unknown> = {};
386	    for (const field of allowedFields) {
387	      if (field in body) {
388	        const dbField = field
389	          .replace(/([A-Z])/g, '_$1')
390	          .toLowerCase() as keyof typeof schema.partInstallations.$inferInsert;
391	        if (field === 'unitCost' || field === 'aircraftHours') {
392	          updates[dbField] =
393	            body[field] !== null && body[field] !== undefined
394	              ? String(body[field])
395	              : null;
396	        } else {
397	          updates[dbField] = body[field];
398	        }
399	      }
400	    }
401	
402	    if (Object.keys(updates).length === 0) {
403	      return c.json({ error: 'No valid fields to update' }, 400);
404	    }
405	
406	    try {
407	      // allowedFields lets the caller repoint workOrderId / logbookEntryId /
408	      // discrepancyId / replacedPartId, so the same scoped check as POST
409	      // applies. Kept inside the try so a DB failure here is handled by the
410	      // route's own error path rather than escaping as an unhandled 500.
411	      const foreignRef = await findForeignReference(body, orgId);
412	      if (foreignRef) return c.json({ error: `Invalid ${foreignRef}` }, 400);
