414	      const [record] = await db
415	        .update(schema.partInstallations)
416	        .set(updates as Partial<typeof schema.partInstallations.$inferInsert>)
417	        .where(
418	          and(
419	            eq(schema.partInstallations.id, id),
420	            eq(schema.partInstallations.flightSchoolId, orgId),
