1	/**
2	 * Aircraft Standby Event Routes
3	 *
4	 * When an aircraft is grounded/in-maintenance, admins can create provisional
5	 * standby events on its schedule row. When the aircraft returns to service
6	 * those events can be activated (converted to live scheduled events) or dismissed.
7	 *
8	 * Routes:
9	 *   POST   /locations/:locationId/schedule/standby-aircraft          — create standby event
10	 *   GET    /locations/:locationId/schedule/standby-aircraft          — list pending standby events (aircraftId query param)
11	 *   POST   /locations/:locationId/schedule/standby-aircraft/:id/activate — activate (conflicts checked)
12	 *   POST   /locations/:locationId/schedule/standby-aircraft/:id/dismiss  — dismiss
13	 *   POST   /locations/:locationId/schedule/standby-aircraft/activate-all — activate all for an aircraft
14	 *   POST   /locations/:locationId/schedule/standby-aircraft/dismiss-all  — dismiss all for an aircraft
15	 */
16	
17	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
18	import { notifyUserViaSms } from '@/lib/notifications';
19	import { scheduleRepository } from '@/repositories/mvp-v2.repository.impl';
20	import { isUuid, resolveOrgIdFromSession } from '@/server/helpers';
21	import { type AuthUser, requireAuth } from '@/server/middleware/auth';
22	import { scheduleTelemetryMiddleware } from '@/server/routes/schedule-telemetry';
23	import { Hono } from 'hono';
24	
25	export const standbyAircraftRoutes = new Hono<{
26	  Variables: { authUser?: AuthUser };
27	}>();
28	
29	standbyAircraftRoutes.use('*', scheduleTelemetryMiddleware());
30	
31	type StandbyRecurrenceRule = {
32	  frequency:
33	    | 'daily'
34	    | 'weekly'
35	    | 'biweekly'
36	    | 'monthly'
37	    | 'weekdays'
38	    | 'custom';
39	  days?: number[];
40	  interval?: number;
41	  unit?: 'days' | 'weeks' | 'months';
42	  monthlyType?: 'day_of_month' | 'weekday_of_month';
43	  monthlyDay?: number;
44	  monthlyWeekday?: {
45	    ordinal: 'first' | 'second' | 'third' | 'fourth' | 'last';
46	    day: number;
47	  };
48	  endType: 'never' | 'count' | 'date';
49	  count?: number;
50	  endDate?: string;
51	};
52	
53	const STANDBY_RECURRENCE_MAX_OCCURRENCES = 52;
54	const DAY_MS = 24 * 60 * 60 * 1000;
55	
56	function recurrenceEndMs(rule: StandbyRecurrenceRule): number | null {
57	  if (rule.endType !== 'date' || !rule.endDate) return null;
58	  const dateOnly = /^\d{4}-\d{2}-\d{2}$/.test(rule.endDate);
59	  const end = new Date(
60	    dateOnly ? `${rule.endDate}T23:59:59.999Z` : rule.endDate,
61	  );
62	  return Number.isNaN(end.getTime()) ? null : end.getTime();
63	}
64	
65	function generateStandbyOccurrenceStarts(
66	  startAt: Date,
67	  recurrenceRule: StandbyRecurrenceRule,
68	): Date[] {
69	  const occurrences: Date[] = [];
70	  const startDayMs = startAt.getTime();
71	  const limit =
72	    recurrenceRule.endType === 'count'
73	      ? Math.min(
74	          Math.max(1, recurrenceRule.count ?? 10),
75	          STANDBY_RECURRENCE_MAX_OCCURRENCES,
76	        )
77	      : STANDBY_RECURRENCE_MAX_OCCURRENCES;
78	  const endMs = recurrenceEndMs(recurrenceRule);
79	
80	  if (recurrenceRule.frequency === 'daily') {
81	    let d = new Date(startDayMs);
82	    while (
83	      occurrences.length < limit &&
84	      (endMs === null || d.getTime() <= endMs)
85	    ) {
86	      occurrences.push(new Date(d.getTime()));
87	      d = new Date(d.getTime() + DAY_MS);
88	    }
89	    return occurrences;
90	  }
91	
92	  if (
93	    recurrenceRule.frequency === 'weekly' ||
94	    recurrenceRule.frequency === 'weekdays' ||
95	    recurrenceRule.frequency === 'biweekly'
96	  ) {
97	    const activeDays =
98	      recurrenceRule.frequency === 'weekdays'
99	        ? [1, 2, 3, 4, 5]
100	        : recurrenceRule.days && recurrenceRule.days.length > 0
101	          ? recurrenceRule.days
102	          : [startAt.getUTCDay()];
103	    let d = new Date(startDayMs);
104	    while (
105	      occurrences.length < limit &&
106	      (endMs === null || d.getTime() <= endMs)
107	    ) {
108	      if (activeDays.includes(d.getUTCDay())) {
109	        occurrences.push(new Date(d.getTime()));
110	      }
111	      d = new Date(d.getTime() + DAY_MS);
112	      if (d.getTime() - startDayMs > 2 * 365 * DAY_MS) break;
113	    }
114	    if (recurrenceRule.frequency === 'biweekly' && occurrences.length > 0) {
115	      const firstOccurrenceMs = occurrences[0].getTime();
116	      return occurrences.filter((occurrence) => {
117	        const diffDays = Math.round(
118	          (occurrence.getTime() - firstOccurrenceMs) / DAY_MS,
119	        );
120	        return Math.floor(diffDays / 7) % 2 === 0;
121	      });
122	    }
123	    return occurrences;
124	  }
125	
126	  const buildMonthlyOccurrence = (year: number, month: number): Date | null => {
127	    const monthlyType = recurrenceRule.monthlyType ?? 'day_of_month';
128	    const timeMs =
129	      startAt.getUTCHours() * 3_600_000 +
130	      startAt.getUTCMinutes() * 60_000 +
131	      startAt.getUTCSeconds() * 1000;
132	    if (monthlyType === 'day_of_month') {
133	      const day = recurrenceRule.monthlyDay ?? startAt.getUTCDate();
134	      const daysInMonth = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
135	      return day <= daysInMonth
136	        ? new Date(Date.UTC(year, month, day) + timeMs)
137	        : null;
138	    }
139	
140	    const { ordinal, day: targetDay } = recurrenceRule.monthlyWeekday ?? {
141	      ordinal: 'first',
142	      day: startAt.getUTCDay(),
143	    };
144	    const ordinalMap: Record<string, number> = {
145	      first: 1,
146	      second: 2,
147	      third: 3,
148	      fourth: 4,
149	      last: -1,
150	    };
151	    const ordinalN = ordinalMap[ordinal] ?? 1;
152	    if (ordinalN === -1) {
153	      const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
154	      for (let day = lastDay; day >= 1; day--) {
155	        const candidate = new Date(Date.UTC(year, month, day));
156	        if (candidate.getUTCDay() === targetDay) {
157	          return new Date(candidate.getTime() + timeMs);
158	        }
159	      }
160	      return null;
161	    }
162	
163	    let count = 0;
164	    for (let day = 1; day <= 31; day++) {
165	      const candidate = new Date(Date.UTC(year, month, day));
166	      if (candidate.getUTCMonth() !== month) break;
167	      if (candidate.getUTCDay() === targetDay) {
168	        count++;
169	        if (count === ordinalN) {
170	          return new Date(candidate.getTime() + timeMs);
171	        }
172	      }
173	    }
174	    return null;
175	  };
176	
177	  if (recurrenceRule.frequency === 'monthly') {
178	    let month = startAt.getUTCMonth();
179	    let year = startAt.getUTCFullYear();
180	    while (occurrences.length < limit && year - startAt.getUTCFullYear() <= 5) {
181	      const occurrence = buildMonthlyOccurrence(year, month);
182	      if (
183	        occurrence &&
184	        occurrence.getTime() >= startDayMs &&
185	        (endMs === null || occurrence.getTime() <= endMs)
186	      ) {
187	        occurrences.push(occurrence);
188	      }
189	      month++;
190	      if (month > 11) {
191	        month = 0;
192	        year++;
193	      }
194	    }
195	    return occurrences;
196	  }
197	
198	  if (recurrenceRule.frequency !== 'custom') return occurrences;
199	
200	  const interval = Math.max(1, recurrenceRule.interval ?? 1);
201	  const unit = recurrenceRule.unit ?? 'weeks';
202	  if (unit === 'days') {
203	    let d = new Date(startDayMs);
204	    while (
205	      occurrences.length < limit &&
206	      (endMs === null || d.getTime() <= endMs)
207	    ) {
208	      occurrences.push(new Date(d.getTime()));
209	      d = new Date(d.getTime() + interval * DAY_MS);
210	      if (d.getTime() - startDayMs > 2 * 365 * DAY_MS) break;
211	    }
212	    return occurrences;
213	  }
214	
215	  if (unit === 'weeks') {
216	    const activeDays =
217	      recurrenceRule.days && recurrenceRule.days.length > 0
218	        ? recurrenceRule.days
219	        : [startAt.getUTCDay()];
220	    const startDayOfWeek = new Date(startDayMs).getUTCDay();
221	    const startSundayMs = startDayMs - startDayOfWeek * DAY_MS;
222	    let d = new Date(startDayMs);
223	    while (
224	      occurrences.length < limit &&
225	      (endMs === null || d.getTime() <= endMs)
226	    ) {
227	      const weekOffset = Math.floor(
228	        (d.getTime() - startSundayMs) / (7 * DAY_MS),
229	      );
230	      if (
231	        weekOffset >= 0 &&
232	        weekOffset % interval === 0 &&
233	        activeDays.includes(d.getUTCDay())
234	      ) {
235	        occurrences.push(new Date(d.getTime()));
236	      }
237	      d = new Date(d.getTime() + DAY_MS);
238	      if (d.getTime() - startDayMs > 2 * 365 * DAY_MS) break;
239	    }
240	    return occurrences;
241	  }
242	
243	  let month = startAt.getUTCMonth();
244	  let year = startAt.getUTCFullYear();
245	  while (occurrences.length < limit && year - startAt.getUTCFullYear() <= 5) {
246	    const occurrence = buildMonthlyOccurrence(year, month);
247	    if (
248	      occurrence &&
249	      occurrence.getTime() >= startDayMs &&
250	      (endMs === null || occurrence.getTime() <= endMs)
251	    ) {
252	      occurrences.push(occurrence);
253	    }
254	    month += interval;
255	    while (month > 11) {
256	      month -= 12;
257	      year++;
258	    }
259	  }
260	  return occurrences;
261	}
