328	      const safeUuid = (value: unknown): string | undefined => {
329	        const id = typeof value === 'string' ? value.trim() : '';
330	        return id && isUuid(id) ? id : undefined;
331	      };
332	      const safeUuidList = (value: unknown): string[] => {
333	        if (!Array.isArray(value)) return [];
334	        return value
335	          .map((id) => (typeof id === 'string' ? id.trim() : ''))
336	          .filter((id): id is string => Boolean(id && isUuid(id)));
337	      };
338	      const safeString = (value: unknown): string | undefined => {
339	        const text = typeof value === 'string' ? value.trim() : '';
340	        return text || undefined;
341	      };
342	      const validStudentIds = safeUuidList(studentIds);
343	      const primaryStudentId = validStudentIds[0] ?? safeUuid(studentId);
344	      const allStudentIds =
345	        validStudentIds.length > 0
346	          ? validStudentIds
347	          : primaryStudentId
348	            ? [primaryStudentId]
349	            : [];
350	      const validInstructorIds = safeUuidList(instructorIds);
351	      const primaryInstructorId =
352	        validInstructorIds[0] ?? safeUuid(instructorId);
353	      const allInstructorIds =
354	        validInstructorIds.length > 0
355	          ? validInstructorIds
356	          : primaryInstructorId
357	            ? [primaryInstructorId]
358	            : [];
359	      const resolvedTitle =
360	        safeString(title) ?? safeString(eventTypeName) ?? 'Standby Flight';
361	      const eventType = safeString(eventTypeId) ?? 'flight';
362	      const recurrence =
363	        recurrenceRule && recurrenceRule.frequency !== undefined
364	          ? recurrenceRule
365	          : undefined;
366	
367	      const eventBase = {
368	        locationId,
369	        title: resolvedTitle,
370	        type: eventType,
371	        aircraftId,
372	        studentId: primaryStudentId,
373	        studentIds: allStudentIds,
374	        instructorId: primaryInstructorId,
375	        instructorIds: allInstructorIds,
376	        trainingModuleId: safeUuid(trainingModuleId),
377	        status: 'standby',
378	        notes: safeString(notes),
379	        notifyOnActivate,
380	      };
381	
382	      if (recurrence) {
383	        const recurrenceGroupId = crypto.randomUUID();
384	        const durationMs = endDate.getTime() - startDate.getTime();
385	        const occurrences = generateStandbyOccurrenceStarts(
386	          startDate,
