394	          );
395	        }
396	
397	        const events = await scheduleRepository.createMany(
398	          orgId,
399	          occurrences.map((occurrenceStart) => ({
400	            ...eventBase,
401	            startAt: occurrenceStart,
402	            endAt: new Date(occurrenceStart.getTime() + durationMs),
403	            recurrenceGroupId,
404	            recurrenceRule: recurrence,
405	          })),
406	        );
407	
408	        return c.json({
409	          success: true,
410	          event: events[0],
411	          events,
412	          instanceCount: events.length,
413	        });
414	      }
415	
416	      const event = await scheduleRepository.create(orgId, {
417	        ...eventBase,
418	        startAt: startDate,
419	        endAt: endDate,
420	      });
421	
422	      return c.json({ success: true, event });
423	    } catch (err: unknown) {
424	      const structured = formatErrorForUser(err, {
