22	import { logAudit } from '@/lib/audit';
23	import { db } from '@/lib/db';
24	import * as schema from '@/lib/schema';
25	import { resolveOrgIdFromSession } from '@/server/helpers';
26	import { requireAuth } from '@/server/middleware/auth';
27	import type { AuthUser } from '@/server/middleware/auth';
28	import { and, asc, count, desc, eq, ilike, isNull, or, sql } from 'drizzle-orm';
29	import { Hono } from 'hono';
30	
31	export const aircraftLogbookRouter = new Hono<{
32	  Variables: { authUser?: AuthUser };
33	}>();
34	
35	// ─── Helpers ──────────────────────────────────────────────────────────────────
36	
37	function isUuid(val: string): boolean {
38	  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
39	    val,
40	  );
41	}
42	
43	function safeErrorMessage(err: unknown): string {
44	  return err instanceof Error
45	    ? err.message
46	    : typeof err === 'object' && err !== null
47	      ? JSON.stringify(err)
48	      : String(err);
49	}
50	
51	/** Entry type to human-readable label */
52	function entryTypeLabel(type: string): string {
53	  const labels: Record<string, string> = {
54	    annual_inspection: 'Annual Inspection',
55	    '100hr_inspection': '100-Hr Inspection',
56	    repair: 'Repair',
57	    alteration: 'Alteration',
58	    ad_compliance: 'AD Compliance',
59	    sb_compliance: 'SB Compliance',
60	    oil_change: 'Oil Change',
61	    component_replacement: 'Component Replacement',
62	    overhaul: 'Overhaul',
63	    progressive_inspection: 'Progressive Inspection',
64	    other_maintenance: 'Other Maintenance',
65	    imported: 'Imported',
66	  };
67	  return labels[type] ?? type;
68	}
