70	/** Logbook type to display name */
71	function logbookTypeLabel(type: string): string {
72	  const labels: Record<string, string> = {
73	    airframe: 'Airframe',
74	    engine: 'Engine',
75	    propeller: 'Propeller',
76	  };
77	  return labels[type] ?? type;
