80	/**
81	 * Ensure the three logbook records exist for an aircraft.
82	 * Creates them if they don't exist yet (lazy initialization).
83	 */
84	async function ensureLogbooks(equipmentId: string, flightSchoolId: string) {
85	  const types = ['airframe', 'engine', 'propeller'] as const;
86	  const existing = await db
87	    .select({ logbookType: schema.aircraftLogbooks.logbookType })
88	    .from(schema.aircraftLogbooks)
89	    .where(eq(schema.aircraftLogbooks.equipmentId, equipmentId));
90	
91	  const existingTypes = new Set(existing.map((r) => r.logbookType));
92	
93	  for (const t of types) {
94	    if (!existingTypes.has(t)) {
95	      await db.insert(schema.aircraftLogbooks).values({
96	        flightSchoolId,
97	        equipmentId,
98	        logbookType: t,
99	      });
100	    }
101	  }
102	}
103	
104	/**
105	 * Tenant isolation helper: verify the requesting user owns the logbook's
106	 * flight school. Returns the flightSchoolId if authorized, or null if the
107	 * logbook doesn't exist. Throws 'FORBIDDEN' if the user's org doesn't match.
108	 */
109	async function verifyLogbookTenant(
110	  logbookId: string,
111	  userOrgId: string | null,
112	): Promise<string | null> {
113	  const [lb] = await db
114	    .select({ flightSchoolId: schema.aircraftLogbooks.flightSchoolId })
115	    .from(schema.aircraftLogbooks)
116	    .where(eq(schema.aircraftLogbooks.id, logbookId))
117	    .limit(1);
118	  if (!lb) return null;
119	  if (userOrgId && lb.flightSchoolId !== userOrgId)
120	    throw new Error('FORBIDDEN');
121	  return lb.flightSchoolId;
122	}
123	
124	/**
125	 * Tenant isolation helper for entry-scoped endpoints.
126	 */
127	async function verifyEntryTenant(
128	  entryId: string,
129	  userOrgId: string | null,
130	): Promise<string | null> {
131	  const [entry] = await db
132	    .select({ logbookId: schema.aircraftLogbookEntries.logbookId })
133	    .from(schema.aircraftLogbookEntries)
134	    .where(eq(schema.aircraftLogbookEntries.id, entryId))
135	    .limit(1);
136	  if (!entry) return null;
137	  return verifyLogbookTenant(entry.logbookId, userOrgId);
138	}
139	
140	// ─── GET /aircraft-logbook/:equipmentId/logbooks ───────────────────────────
141	
142	aircraftLogbookRouter.get(
143	  '/aircraft-logbook/:equipmentId/logbooks',
144	  requireAuth(),
145	  async (c) => {
146	    const { equipmentId } = c.req.param();
147	    if (!isUuid(equipmentId))
148	      return c.json({ error: 'Invalid equipment ID' }, 400);
149	
150	    try {
151	      // Tenant isolation: resolve the requesting user's org
152	      const authUser = c.get('authUser') as AuthUser;
153	      const userOrgId = await resolveOrgIdFromSession(authUser, c);
154	
155	      // Fetch aircraft metadata
156	      const [aircraft] = await db
157	        .select({
158	          id: schema.equipment.id,
159	          flightSchoolId: schema.equipment.flightSchoolId,
160	          tailNumber: schema.equipment.tailNumber,
161	          make: schema.equipment.make,
162	          model: schema.equipment.model,
163	          year: schema.equipment.year,
164	          hobbsTime: schema.equipment.hobbsTime,
165	          totalHours: schema.equipment.totalHours,
166	        })
167	        .from(schema.equipment)
168	        .where(eq(schema.equipment.id, equipmentId))
169	        .limit(1);
170	
171	      if (!aircraft) return c.json({ error: 'Equipment not found' }, 404);
172	
173	      // Verify the aircraft belongs to the user's organization
174	      if (userOrgId && aircraft.flightSchoolId !== userOrgId) {
175	        return c.json({ error: 'Forbidden' }, 403);
176	      }
177	
178	      // Ensure logbook records exist
179	      await ensureLogbooks(equipmentId, aircraft.flightSchoolId);
180	
181	      // Fetch all three logbooks
182	      const logbooks = await db
183	        .select()
184	        .from(schema.aircraftLogbooks)
185	        .where(eq(schema.aircraftLogbooks.equipmentId, equipmentId));
186	
187	      // For each logbook, compute stats
188	      const logbooksWithStats = await Promise.all(
189	        logbooks.map(async (lb) => {
190	          const entries = await db
191	            .select({
192	              id: schema.aircraftLogbookEntries.id,
193	              entryType: schema.aircraftLogbookEntries.entryType,
194	              entryDate: schema.aircraftLogbookEntries.entryDate,
195	              aircraftTotalTime:
196	                schema.aircraftLogbookEntries.aircraftTotalTime,
197	              source: schema.aircraftLogbookEntries.source,
198	              signedAt: schema.aircraftLogbookEntries.signedAt,
199	            })
200	            .from(schema.aircraftLogbookEntries)
201	            .where(eq(schema.aircraftLogbookEntries.logbookId, lb.id))
202	            .orderBy(desc(schema.aircraftLogbookEntries.entryDate));
203	
204	          const entryCount = entries.length;
205	          const pendingAutoCount = entries.filter(
206	            (e) => e.source === 'auto' && e.signedAt === null,
207	          ).length;
208	
209	          // Most recent entry by type
210	          const lastAnnual = entries.find(
211	            (e) => e.entryType === 'annual_inspection',
212	          );
213	          const last100hr = entries.find(
214	            (e) => e.entryType === '100hr_inspection',
215	          );
216	          const lastOilChange = entries.find(
217	            (e) => e.entryType === 'oil_change',
218	          );
219	
220	          // Total time from most recent entry
221	          const latestEntry = entries[0];
222	          const currentTotalTime = latestEntry?.aircraftTotalTime
223	            ? Number(latestEntry.aircraftTotalTime)
224	            : null;
225	
226	          // 100-hr: hours until next (100-hr entry + 100 - current hobbs)
227	          const last100hrTime = last100hr?.aircraftTotalTime
228	            ? Number(last100hr.aircraftTotalTime)
229	            : null;
230	          const hoursUntil100hr =
231	            last100hrTime !== null && currentTotalTime !== null
232	              ? Math.max(0, last100hrTime + 100 - currentTotalTime)
233	              : null;
234	
235	          return {
236	            id: lb.id,
237	            equipmentId: lb.equipmentId,
238	            logbookType: lb.logbookType,
239	            displayName: logbookTypeLabel(lb.logbookType),
240	            entryCount,
241	            pendingAutoCount,
242	            currentTotalTime,
243	            lastAnnualDate: lastAnnual?.entryDate ?? null,
244	            lastAnnualTime: lastAnnual?.aircraftTotalTime
245	              ? Number(lastAnnual.aircraftTotalTime)
246	              : null,
247	            last100hrDate: last100hr?.entryDate ?? null,
248	            last100hrTime,
249	            hoursUntil100hr,
250	            lastOilChangeDate: lastOilChange?.entryDate ?? null,
251	            createdAt: lb.createdAt,
252	          };
253	        }),
254	      );
255	
256	      // Sort: airframe, engine, propeller
257	      const order = ['airframe', 'engine', 'propeller'];
258	      logbooksWithStats.sort(
259	        (a, b) => order.indexOf(a.logbookType) - order.indexOf(b.logbookType),
260	      );
261	
262	      return c.json({
263	        aircraft,
264	        logbooks: logbooksWithStats,
265	      });
266	    } catch (err) {
267	      console.error(
268	        '[aircraft-logbook] GET logbooks failed:',
269	        safeErrorMessage(err),
270	      );
271	      return c.json({ error: 'Failed to load logbooks' }, 500);
272	    }
273	  },
274	);
275	
276	// ─── GET /aircraft-logbook/:logbookId/entries ─────────────────────────────
277	
278	aircraftLogbookRouter.get(
279	  '/aircraft-logbook/:logbookId/entries',
280	  requireAuth(),
281	  async (c) => {
282	    const { logbookId } = c.req.param();
283	    if (!isUuid(logbookId)) return c.json({ error: 'Invalid logbook ID' }, 400);
284	
285	    const {
286	      type,
287	      source,
288	      signed,
289	      search,
290	      sort = 'newest',
291	      page = '1',
292	      limit: limitStr = '100',
293	    } = c.req.query();
294	
295	    const pageNum = Math.max(1, Number.parseInt(page, 10) || 1);
296	    const limitNum = Math.min(
297	      500,
298	      Math.max(1, Number.parseInt(limitStr, 10) || 100),
299	    );
300	    const offset = (pageNum - 1) * limitNum;
301	
302	    try {
303	      // Tenant isolation
304	      const authUser = c.get('authUser') as AuthUser;
305	      const userOrgId = await resolveOrgIdFromSession(authUser, c);
306	      const schoolId = await verifyLogbookTenant(logbookId, userOrgId);
307	      if (!schoolId) return c.json({ error: 'Logbook not found' }, 404);
308	
309	      const conditions = [
310	        eq(schema.aircraftLogbookEntries.logbookId, logbookId),
311	      ];
312	
313	      // Filter by entry type
314	      if (type) {
315	        if (type === 'repairs') {
316	          conditions.push(
317	            or(
318	              eq(schema.aircraftLogbookEntries.entryType, 'repair'),
319	              eq(schema.aircraftLogbookEntries.entryType, 'alteration'),
320	              eq(
321	                schema.aircraftLogbookEntries.entryType,
322	                'component_replacement',
323	              ),
324	            )!,
325	          );
326	        } else if (type === 'ads') {
327	          conditions.push(
328	            eq(schema.aircraftLogbookEntries.entryType, 'ad_compliance'),
329	          );
330	        } else {
331	          conditions.push(eq(schema.aircraftLogbookEntries.entryType, type));
332	        }
333	      }
334	
335	      // Filter by source
336	      if (source) {
337	        conditions.push(eq(schema.aircraftLogbookEntries.source, source));
338	      }
339	
340	      // Filter by signed status
341	      if (signed === 'false') {
342	        conditions.push(isNull(schema.aircraftLogbookEntries.signedAt));
343	      } else if (signed === 'true') {
344	        conditions.push(
345	          sql`${schema.aircraftLogbookEntries.signedAt} IS NOT NULL`,
346	        );
347	      }
348	
349	      // Search
350	      if (search?.trim()) {
351	        const q = `%${search.trim()}%`;
352	        conditions.push(
353	          or(
354	            ilike(schema.aircraftLogbookEntries.entryText, q),
355	            ilike(schema.aircraftLogbookEntries.performedBy, q),
356	            ilike(schema.aircraftLogbookEntries.apCertNumber, q),
357	            ilike(schema.aircraftLogbookEntries.entryNumber, q),
358	          )!,
359	        );
360	      }
361	
362	      const orderBy =
363	        sort === 'oldest'
364	          ? asc(schema.aircraftLogbookEntries.entryDate)
365	          : desc(schema.aircraftLogbookEntries.entryDate);
366	
367	      const [entries, [{ total }]] = await Promise.all([
368	        db
369	          .select()
370	          .from(schema.aircraftLogbookEntries)
371	          .where(and(...conditions))
372	          .orderBy(orderBy)
