275	export async function resolveOrgIdFromEmail(
276	  email: string,
277	): Promise<string | null> {
278	  try {
279	    const [result] = await db
280	      .select({ flightSchoolId: schema.users.flightSchoolId })
281	      .from(schema.users)
282	      .where(eq(schema.users.email, email.toLowerCase()))
283	      // Deterministic primary-row selection for multi-school emails (otherwise
284	      // an arbitrary school's row scopes the whole request).
285	      .orderBy(...primaryUserRowOrderBy())
286	      .limit(1);
287	    if (result?.flightSchoolId) return result.flightSchoolId;
288	
289	    // Location Admins exist in team_members, not users — fall back to that
290	    // table. team_members.email is not normalized on write, so match
291	    // case-insensitively and order deterministically.
292	    const [member] = await db
293	      .select({ flightSchoolId: schema.teamMembers.flightSchoolId })
294	      .from(schema.teamMembers)
295	      .where(sql`lower(${schema.teamMembers.email}) = ${email.toLowerCase()}`)
296	      .orderBy(...primaryTeamMemberRowOrderBy())
297	      .limit(1);
298	    return member?.flightSchoolId ?? null;
299	  } catch (err) {
300	    Sentry.captureException(err, {
301	      tags: { feature: 'helpers', op: 'resolveOrgIdFromEmail' },
302	    });
303	    throw err;
304	  }
305	}
