36	function normalizeNumber(value: unknown): number | null {
37	  if (value === null || value === undefined || value === '') return null;
38	  const n =
39	    typeof value === 'number' ? value : Number.parseFloat(String(value));
40	  return Number.isFinite(n) ? n : null;
41	}
42	
43	function toIsoDate(value: unknown): string | null {
44	  if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
45	    return value;
46	  }
47	  const d = value instanceof Date ? value : new Date(String(value));
48	  if (Number.isNaN(d.getTime())) return null;
49	  return d.toISOString().slice(0, 10);
50	}
51	
52	function daysBetweenUtcDates(fromIsoDate: string, toDate = new Date()): number {
53	  const from = new Date(`${fromIsoDate}T00:00:00.000Z`);
54	  const to = new Date(
55	    Date.UTC(
56	      toDate.getUTCFullYear(),
57	      toDate.getUTCMonth(),
58	      toDate.getUTCDate(),
59	    ),
60	  );
61	  return Math.floor((to.getTime() - from.getTime()) / 86_400_000);
62	}
