123	function computeWithinTolerance(
124	  checkType: VorCheckType,
125	  bearingErrorDeg: number | null,
126	  vor1ErrorDeg: number | null,
127	  vor2ErrorDeg: number | null,
128	): boolean {
129	  if (checkType === 'vot' || checkType === 'ground_checkpoint') {
130	    if (bearingErrorDeg === null) return false;
131	    return Math.abs(bearingErrorDeg) <= 4;
132	  }
133	  if (checkType === 'airborne_checkpoint') {
134	    if (bearingErrorDeg === null) return false;
135	    return Math.abs(bearingErrorDeg) <= 6;
136	  }
137	  if (checkType === 'dual_vor') {
138	    if (vor1ErrorDeg === null || vor2ErrorDeg === null) return false;
139	    return Math.abs(vor1ErrorDeg - vor2ErrorDeg) <= 4;
140	  }
141	  return false;
142	}
