148	  const bearingErrorDeg = normalizeNumber(row.bearingErrorDeg);
149	  const vor1ErrorDeg = normalizeNumber(row.vor1ErrorDeg);
150	  const vor2ErrorDeg = normalizeNumber(row.vor2ErrorDeg);
151	  const computedWithinTolerance = computeWithinTolerance(
152	    row.checkType as VorCheckType,
153	    bearingErrorDeg,
154	    vor1ErrorDeg,
155	    vor2ErrorDeg,
156	  );
157	
158	  return {
159	    id: row.id,
160	    aircraft_id: row.aircraftId,
161	    check_date: checkDate,
162	    check_type: row.checkType,
163	    place_of_check: row.placeOfCheck,
