168	    within_tolerance: row.withinTolerance,
169	    within_tolerance_computed: computedWithinTolerance,
170	    performed_by_user_id: row.performedByUserId,
171	    performed_by_name: row.performedByName,
172	    certificate_number: row.certificateNumber,
173	    signature_text: row.signatureText,
