224	function collectFieldChanges(
225	  existing: typeof schema.vorChecks.$inferSelect,
226	  next: {
227	    checkDate: string;
228	    checkType: VorCheckType;
229	    placeOfCheck: string;
230	    vorFrequency: string | null;
231	    bearingErrorDeg: number | null;
232	    vor1ErrorDeg: number | null;
233	    vor2ErrorDeg: number | null;
234	    withinTolerance: boolean;
235	    performedByName: string;
236	    certificateNumber: string;
237	    signatureText: string;
238	    remarks: string | null;
239	  },
240	): Record<string, { from: unknown; to: unknown }> {
241	  const map: Array<[string, unknown, unknown]> = [
242	    ['check_date', toIsoDate(existing.checkDate), next.checkDate],
243	    ['check_type', existing.checkType, next.checkType],
244	    ['place_of_check', existing.placeOfCheck, next.placeOfCheck],
245	    ['vor_frequency', existing.vorFrequency, next.vorFrequency],
246	    [
247	      'bearing_error_deg',
248	      normalizeNumber(existing.bearingErrorDeg),
249	      next.bearingErrorDeg,
250	    ],
251	    [
252	      'vor1_error_deg',
253	      normalizeNumber(existing.vor1ErrorDeg),
254	      next.vor1ErrorDeg,
255	    ],
256	    [
257	      'vor2_error_deg',
258	      normalizeNumber(existing.vor2ErrorDeg),
259	      next.vor2ErrorDeg,
260	    ],
261	    ['within_tolerance', existing.withinTolerance, next.withinTolerance],
262	    ['performed_by_name', existing.performedByName, next.performedByName],
263	    ['certificate_number', existing.certificateNumber, next.certificateNumber],
264	    ['signature_text', existing.signatureText, next.signatureText],
265	    ['remarks', existing.remarks, next.remarks],
266	  ];
267	
268	  const changes: Record<string, { from: unknown; to: unknown }> = {};
269	  for (const [field, from, to] of map) {
270	    if (from !== to) {
271	      changes[field] = { from, to };
272	    }
273	  }
274	  return changes;
275	}
