122	// ─── Camera Scanner ───────────────────────────────────────────────────────────
123	// Fills its container absolutely — place inside a positioned parent.
124	// Scan line is NOT rendered here; callers place it inside the viewfinder box.
125	
126	function CameraScanner({
127	  onDetected,
128	  onError,
129	}: {
130	  onDetected: (partId: string) => void;
131	  onError: (msg: string) => void;
132	}) {
133	  const videoRef = useRef<HTMLVideoElement>(null);
134	  const streamRef = useRef<MediaStream | null>(null);
135	  const detectingRef = useRef(false);
136	  const animRef = useRef<number>(0);
137	  const zxingControlsRef = useRef<{ stop: () => void } | null>(null);
138	
139	  useEffect(() => {
140	    let mounted = true;
141	
142	    async function startCamera() {
143	      try {
144	        const stream = await navigator.mediaDevices.getUserMedia({
145	          video: {
146	            facingMode: 'environment',
147	            width: { ideal: 1920 },
148	            height: { ideal: 1080 },
149	          },
150	        });
151	        streamRef.current = stream;
152	        if (videoRef.current && mounted) {
153	          videoRef.current.srcObject = stream;
154	          await videoRef.current.play();
155	          startDetecting();
156	        }
157	      } catch (err) {
158	        const msg = err instanceof Error ? err.message : 'Camera access denied';
159	        if (mounted) onError(msg);
160	      }
161	    }
162	
163	    function startDetecting() {
164	      if (isBarcodeDetectorSupported() && window.BarcodeDetector) {
165	        startBarcodeDetectorLoop();
166	      } else {
167	        void startZxingLoop();
168	      }
169	    }
170	
171	    function startBarcodeDetectorLoop() {
172	      if (!window.BarcodeDetector) return;
173	      const detector = new window.BarcodeDetector({ formats: ['qr_code'] });
174	
175	      async function tick() {
176	        if (!mounted || detectingRef.current) return;
177	        const video = videoRef.current;
178	        if (!video || video.readyState < 2) {
179	          animRef.current = requestAnimationFrame(tick);
180	          return;
181	        }
182	        detectingRef.current = true;
183	        try {
184	          const barcodes = await detector.detect(video);
185	          for (const barcode of barcodes) {
186	            if (barcode.rawValue.startsWith(QR_PREFIX)) {
187	              const partId = barcode.rawValue.slice(QR_PREFIX.length).trim();
188	              if (partId && mounted) {
189	                onDetected(partId);
190	                return;
191	              }
192	            }
193	          }
194	        } catch {
195	          // BarcodeDetector throws on invalid frames — continue
196	        } finally {
197	          detectingRef.current = false;
198	        }
199	        animRef.current = requestAnimationFrame(tick);
200	      }
201	
202	      animRef.current = requestAnimationFrame(tick);
203	    }
204	
205	    async function startZxingLoop() {
206	      // Fallback for Safari iOS and Firefox — BarcodeDetector not supported there
207	      try {
208	        const { BrowserQRCodeReader } = await import('@zxing/browser');
209	        const codeReader = new BrowserQRCodeReader();
210	        const video = videoRef.current;
211	        if (!video || !mounted) return;
212	        const controls = await codeReader.decodeFromVideoElement(
213	          video,
214	          (result) => {
215	            if (!mounted || !result) return;
216	            const rawValue = result.getText();
217	            if (rawValue.startsWith(QR_PREFIX)) {
218	              const partId = rawValue.slice(QR_PREFIX.length).trim();
219	              if (partId) {
220	                zxingControlsRef.current?.stop();
221	                onDetected(partId);
222	              }
223	            }
224	          },
225	        );
226	        zxingControlsRef.current = controls;
227	      } catch {
228	        // zxing throws on unmount cleanup — ignore
229	      }
230	    }
231	
232	    void startCamera();
233	
234	    return () => {
235	      mounted = false;
236	      cancelAnimationFrame(animRef.current);
237	      zxingControlsRef.current?.stop();
238	      streamRef.current?.getTracks().forEach((t) => t.stop());
239	    };
240	  }, [onDetected, onError]);
241	
242	  return (
243	    <div className="absolute inset-0 overflow-hidden bg-black">
244	      <video
245	        ref={videoRef}
246	        muted
247	        playsInline
248	        className="w-full h-full object-cover"
249	      />
250	    </div>
251	  );
252	}
