52	type EquipmentStatus =
53	  | 'active'
54	  | 'available'
55	  | 'in use'
56	  | 'grounded'
57	  | 'maintenance'
58	  | 'inactive'
59	  | 'retired';
60	type EquipmentType = 'aircraft' | 'simulator';
61	
62	/**
63	 * Maps DB enum values (PascalCase) to the component's internal lowercase representation.
64	 * DB returns 'Aircraft' | 'Simulator'; component uses 'aircraft' | 'simulator'.
65	 */
66	function normalizeEquipmentType(raw: string): EquipmentType {
67	  return raw.toLowerCase() === 'simulator' ? 'simulator' : 'aircraft';
68	}
69	
70	/**
71	 * Maps DB enum values to the component's internal status representation.
72	 * DB returns 'Active' | 'Available' | 'In Use' | 'Maintenance' | 'Out of Service'
73	 *          | 'Grounded' | 'Inactive' | 'Retired'.
74	 */
75	function normalizeEquipmentStatus(raw: string): EquipmentStatus {
76	  const s = raw.toLowerCase();
77	  if (s === 'maintenance') return 'maintenance';
78	  if (s === 'grounded' || s === 'out of service') return 'grounded';
79	  if (s === 'inactive') return 'inactive';
80	  if (s === 'retired') return 'retired';
81	  if (s === 'available') return 'available';
82	  if (s === 'in use') return 'in use';
83	  return 'active'; // 'Active' or anything else → active
84	}
