52	function formatHour(hour?: number | null): string {
53	  if (hour == null) return '';
54	  const h = Math.floor(hour);
55	  const m = Math.round((hour - h) * 60);
56	  const ampm = h >= 12 ? 'PM' : 'AM';
57	  const displayH = h % 12 || 12;
58	  return `${displayH}:${String(m).padStart(2, '0')} ${ampm}`;
59	}
