58	function deriveStatus(
59	  qtyAvailable: number,
60	  reorderPoint: number | null,
61	  shelfLifeExpiry: Date | null,
62	): string {
63	  if (qtyAvailable <= 0) return 'out_of_stock';
64	
65	  if (shelfLifeExpiry) {
66	    const daysUntilExpiry =
67	      (shelfLifeExpiry.getTime() - Date.now()) / (1000 * 60 * 60 * 24);
68	    if (daysUntilExpiry <= 30) return 'expiring_soon';
69	    if (daysUntilExpiry < 0) return 'expired';
70	  }
71	
72	  if (reorderPoint !== null && qtyAvailable <= reorderPoint) {
73	    return 'low_stock';
74	  }
75	
76	  return 'in_stock';
77	}

